/// Run a command by its words and give the exit code: 0 ok, 1 the other side answered with an error, 2 a wrong
/// word or value, 3 not reachable or a call of a watch could not be read. `wait` is what the program does while a
/// watch runs (until the user stops it) and says why it ended: `Ok` if the user stopped it, an error if the connection
/// was lost (`Disconnected` is 3); the code is made after it, from that and from what the listeners counted.
pub async fn run_to_exit<W, F>(root: &::fs_interfaces::tasks_capnp::tasks::Client, words: &[&str], inp: &mut dyn Input, out: &mut dyn Output, wait: W) -> i32 where W: FnOnce() -> F, F: ::core::future::Future<Output = Result<(), CallError>> {
    let result = match dispatch(words) {
        Some(go) => go(root, inp, out).await,
        None => Err(CallError::at("", ErrorKind::BadValue(format!("no command `{}`", words.join(" "))))),
    };
    let result = match result {
        Ok(o) if o.is_watching() => wait().await.map(|()| o),
        other => other,
    };
    capnp_compiler::cligen::rt::exit_code(&result)
}

