/// Receives the calls of `ChangeListener` and hands each to the sink as one line.
pub struct ChangeListenerLines<S: Sink> {
    sink: ::core::cell::RefCell<S>,
    errors: ::std::rc::Rc<::core::cell::Cell<u32>>,
}

impl<S: Sink> ChangeListenerLines<S> {
    pub fn new(sink: S) -> Self {
        Self { sink: ::core::cell::RefCell::new(sink), errors: ::std::rc::Rc::default() }
    }

    /// How many calls could not be read: counted here, whatever the sink does with the line.
    pub fn errors(&self) -> ::std::rc::Rc<::core::cell::Cell<u32>> {
        self.errors.clone()
    }
}

impl<S: Sink> ::fs_interfaces::common_capnp::change_listener::Server for ChangeListenerLines<S> {
    fn change(self: ::capnp::capability::Rc<Self>, params: ::fs_interfaces::common_capnp::change_listener::ChangeParams) -> impl ::core::future::Future<Output = Result<(), ::capnp::Error>> + 'static {
        match params.get() {
            Ok(p) => { if out_common_capnp_change_listener_change_params(p, "", &mut capnp_compiler::cligen::rt::Discard).is_err() { self.errors.set(self.errors.get() + 1); } self.sink.borrow_mut().line("change", &mut |out| out_common_capnp_change_listener_change_params(p, "", out)); }
            Err(e) => { self.errors.set(self.errors.get() + 1); let why = e.to_string(); self.sink.borrow_mut().line("change", &mut |_| Err(CallError::at("", ErrorKind::BadValue(why.clone())))); }
        }
        ::core::future::ready(Ok(()))
    }
    fn ended(self: ::capnp::capability::Rc<Self>, params: ::fs_interfaces::common_capnp::change_listener::EndedParams, _results: ::fs_interfaces::common_capnp::change_listener::EndedResults) -> impl ::core::future::Future<Output = Result<(), ::capnp::Error>> + 'static {
        match params.get() {
            Ok(p) => { if out_common_capnp_change_listener_ended_params(p, "", &mut capnp_compiler::cligen::rt::Discard).is_err() { self.errors.set(self.errors.get() + 1); } self.sink.borrow_mut().line("ended", &mut |out| out_common_capnp_change_listener_ended_params(p, "", out)); }
            Err(e) => { self.errors.set(self.errors.get() + 1); let why = e.to_string(); self.sink.borrow_mut().line("ended", &mut |_| Err(CallError::at("", ErrorKind::BadValue(why.clone())))); }
        }
        ::core::future::ready(Ok(()))
    }
}

